import {currentZone} from './abilities.js';
import * as T from './vendor/three.module.js';
import {height} from './island.js';
export const SEA_LEVEL=-.8;
export const diveZones=[currentZone,{id:'lagoon',name:'Le lagon des poissons',x:0,z:50,r:8},{id:'ruins',name:'Les fonds oubliés',x:18,z:74,r:11}];
export function diveZone(x,z){return height(Math.round(x),Math.round(z))===-2?diveZones.find(p=>Math.hypot(x-p.x,z-p.z)<p.r)||null:null;}
export function seabed(x,z){const p=diveZone(x,z);return p?-3-Math.floor(Math.min(6,(p.r-Math.hypot(x-p.x,z-p.z))*.8)):null;}
export function swimHeight(y,floor,descending,dt){const target=descending?floor+1.15:SEA_LEVEL+1.2;return T.MathUtils.clamp(y+Math.sign(target-y)*Math.min(Math.abs(target-y),dt*2.4),floor+1.05,Math.max(y,SEA_LEVEL+1.2));}
export function normalizeMarine(saved){return {treasure:!!saved?.treasure,seen:Array.isArray(saved?.seen)?saved.seen.filter(n=>['coelacanth','ammonite','croc','dunk'].includes(n)):[],retreats:Object.fromEntries(['croc','dunk'].map(id=>[id,Math.max(0,Math.min(90,Number(saved?.retreats?.[id])||0))]))};}
export function claimMarineTreasure(state,inv,pos,chest){if(state.treasure||pos.y>=SEA_LEVEL-.35||pos.distanceTo(chest)>2.3)return false;state.treasure=true;inv.gems=(inv.gems||0)+25;return true;}
export const marineSpecies={coelacanth:{name:'Cœlacanthe',color:0x64aab9,hp:0},ammonite:{name:'Ammonite',color:0xe6ae77,hp:0},croc:{name:'Sarcosuchus · crocodile géant',color:0x77965e,hp:3},dunk:{name:'Dunkleosteus · poisson cuirassé',color:0x75849f,hp:5}};
const bodyGeo=new T.SphereGeometry(1,10,7),cube=new T.BoxGeometry(1,1,1);
function part(g,geo,color,x,y,z,sx,sy,sz){const m=new T.Mesh(geo,new T.MeshLambertMaterial({color,flatShading:true}));m.position.set(x,y,z);m.scale.set(sx,sy,sz);g.add(m);return m;}
export function makeMarineAnimal(kind){const g=new T.Group(),s=marineSpecies[kind],tail=new T.Group();
 if(kind==='ammonite'){part(g,bodyGeo,s.color,0,0,0,.42,.45,.2);const spiral=new T.Mesh(new T.TorusGeometry(.26,.055,5,18),new T.MeshLambertMaterial({color:0x966146}));spiral.position.z=-.2;g.add(spiral);part(g,bodyGeo,0xffdec0,0,-.22,-.35,.19,.17,.3);for(let i=0;i<5;i++)part(g,cube,0xffdec0,(i-2)*.07,-.28,-.65,.04,.05,.4);}
 else {const croc=kind==='croc',big=kind==='dunk';part(g,bodyGeo,s.color,0,0,0,croc?.55:big?.65:.23,croc?.3:big?.62:.32,croc?1.45:big?1.05:.7);part(g,bodyGeo,s.color,0,.02,croc?-1.5:big?-.9:-.5,croc?.36:big?.63:.25,croc?.16:big?.49:.27,croc?.85:.5);tail.position.z=croc?1.2:big?.95:.65;g.add(tail);part(tail,bodyGeo,s.color,0,0,.35,croc?.25:.07,croc?.13:.42,croc?.8:.3);
 for(const side of [-1,1]){part(g,bodyGeo,s.color,side*(croc?.65:big?.65:.32),-.15,.1,croc?.4:.35,.07,.24);part(g,bodyGeo,0xfff1bb,side*(croc?.27:big?.48:.18),.16,croc?-1.7:big?-1.1:-.65,.09,.09,.08);part(g,bodyGeo,0x193d44,side*(croc?.27:big?.48:.18),.17,croc?-1.77:big?-1.17:-.72,.045,.05,.035);if(croc)part(g,bodyGeo,s.color,side*.65,-.15,.8,.4,.07,.25);}
 if(big)part(g,cube,0xc2c0aa,0,-.16,-1.36,.85,.11,.08);if(croc)for(let i=0;i<6;i++)part(g,cube,0x425e3b,0,.3,-.65+i*.34,.22,.13,.18);}
 return {g,tail};}
export class MarineWorld{
 constructor({scene,ground,saved,onChange,onDamage,message,sound,inv,blocked}){Object.assign(this,{scene,ground,onChange,onDamage,message,sound,inv,blocked});this.state=normalizeMarine(saved);this.animals=[];
 const spawns=[['coelacanth',-3,48],['coelacanth',2,49],['coelacanth',-1,52],['ammonite',2,52],['ammonite',16,72],['coelacanth',20,73],['croc',3,50],['dunk',19,77]];
 spawns.forEach(([kind,x,z],i)=>{const model=makeMarineAnimal(kind),s=marineSpecies[kind],a={...model,id:"marine-"+i,kind,x,z,hp:s.hp,retreat:this.state.retreats[kind]||0,hit:0,phase:i*1.9};a.g.position.set(x,ground(x,z,true)+2,z);scene.add(a.g);this.animals.push(a);});
 for(const zone of diveZones){const buoy=new T.Group();part(buoy,cube,0xf6d378,0,0,0,.7,.25,.7);part(buoy,cube,0xfff2cc,0,.65,0,.06,1.3,.06);part(buoy,cube,0x37b2b4,.3,1,0,.6,.4,.06);buoy.position.set(zone.x,SEA_LEVEL+.2,zone.z);scene.add(buoy);}
 for(const zone of diveZones)for(let i=0;i<14;i++){const x=Math.round(zone.x+Math.sin(i*2.4)*(2+i%5)),z=Math.round(zone.z+Math.cos(i*2.4)*(2+i%5));if(!diveZone(x,z))continue;const coral=new T.Group(),y=ground(x,z,true);for(let j=0;j<3;j++)part(coral,cube,i%2?0xc78498:0x5eaaa0,(j-1)*.16,.25+j*.1,0,.09,.5+j*.2,.1);coral.position.set(x,y,z);scene.add(coral);}
 this.chest=new T.Group();part(this.chest,cube,0x866447,0,.25,0,.9,.5,.65);part(this.chest,cube,0xf4cd59,0,.54,0,.95,.12,.7);for(const x of [-.3,.3])part(this.chest,cube,0xf4cd59,x,.25,0,.09,.55,.68);part(this.chest,cube,0xffed94,0,.25,-.35,.18,.18,.06);this.chest.position.set(18,ground(18,75,true),75);this.chest.visible=!this.state.treasure;scene.add(this.chest);
 // Broken pillars make the treasure site recognizable from a distance.
 for(const x of [15,21])for(const z of [73,77]){const pillar=new T.Group();part(pillar,cube,0x8cad9c,0,.7,0,.65,1.4,.65);part(pillar,cube,0xa8c7ad,0,1.45,0,.85,.15,.85);pillar.position.set(x,ground(x,z,true),z);scene.add(pillar);}}
 target(pos,yaw){return this.animals.filter(a=>marineSpecies[a.kind].hp&&a.retreat<=0&&a.g.position.distanceTo(pos)<3.6&&Math.abs(a.g.position.y-pos.y)<2.4&&(-Math.sin(yaw)*(a.g.position.x-pos.x)-Math.cos(yaw)*(a.g.position.z-pos.z))>0).sort((a,b)=>a.g.position.distanceTo(pos)-b.g.position.distanceTo(pos))[0];}
 strike(a,time){if(time<a.hit)return;a.hit=time+.55;a.hp--;this.sound('hit');if(a.hp<=0){a.retreat=90;a.hp=marineSpecies[a.kind].hp;this.message('Bravo ! Le prédateur marin s’éloigne.');this.sound('victory');}else this.message(marineSpecies[a.kind].name+' · encore '+a.hp+' coups pour le repousser');this.onChange();}
 update(dt,time,pos,underwater){let hint='';for(const a of this.animals){a.retreat=Math.max(0,a.retreat-dt);a.g.visible=!a.foodAbsent&&a.retreat<=0&&a.g.position.distanceTo(pos)<110;if(!a.g.visible)continue;const s=marineSpecies[a.kind],distance=a.g.position.distanceTo(pos);if(underwater&&distance<9&&!this.state.seen.includes(a.kind)){this.state.seen.push(a.kind);this.message('🐠 '+s.name+' découvert !');this.onChange();}const chase=s.hp&&underwater&&distance<7,angle=a.ecoGoal&&!chase?Math.atan2(a.ecoGoal.x-a.g.position.x,a.ecoGoal.z-a.g.position.z):chase?Math.atan2(pos.x-a.g.position.x,pos.z-a.g.position.z):time*.25+a.phase,speed=chase?1.15:.45,x=a.g.position.x+Math.sin(angle)*speed*dt,z=a.g.position.z+Math.cos(angle)*speed*dt;const home=diveZone(a.x,a.z);if(diveZone(x,z)?.id===home.id&&Math.hypot(x-a.x,z-a.z)<5){const bottom=this.ground(x,z,true),y=T.MathUtils.clamp(chase?pos.y:bottom+2+Math.sin(time+a.phase)*.3,bottom+.7,SEA_LEVEL-.8);if(bottom<SEA_LEVEL-1&&!this.blocked(a.g.position,new T.Vector3(x,y,z))){a.g.position.x=x;a.g.position.z=z;a.g.position.y=T.MathUtils.lerp(a.g.position.y,y,Math.min(1,dt*2));a.g.rotation.y=angle+Math.PI;}}a.tail.rotation.y=Math.sin(time*5+a.phase)*.3;if(chase&&distance<1.5&&time>=a.hit&&!this.blocked(a.g.position,pos))this.onDamage(1);if(chase&&distance<5)hint='⚔️ '+s.name+' · '+a.hp+' ♥ · Frappe ou remonte';}
 if(underwater&&!this.state.treasure&&pos.distanceTo(this.chest.position)<7)hint=hint||'✨ Un coffre marin ! Approche-toi pour l’ouvrir';if(underwater&&!this.state.treasure&&pos.distanceTo(this.chest.position)<3&&!this.blocked(pos,this.chest.position.clone().add(new T.Vector3(0,.7,0)))&&claimMarineTreasure(this.state,this.inv,pos,this.chest.position.clone().add(new T.Vector3(0,.5,0)))){this.chest.visible=false;this.message('Trésor marin découvert ! +25 gemmes 💎');this.sound('treasure');this.onChange();}return hint;}
 serialize(){return {...this.state,retreats:Object.fromEntries(this.animals.filter(a=>marineSpecies[a.kind].hp).map(a=>[a.kind,a.retreat]))};}
}
